/bin/zsh -lc "cat > .relay-check/webview.js <<'EOF'
ObjC.import('AppKit');
ObjC.import('WebKit');
function run(argv) {
  const root = argv[0];
  const web = "'$.WebView.alloc.initWithFrameFrameNameGroupName($.NSMakeRect(0,0,1440,900), '"'relay', 'relay-test');
  web.preferences.javaScriptEnabled = true;
  web.preferences.privateBrowsingEnabled = true;
  function js(code) {
    const result = web.stringByEvaluatingJavaScriptFromString('(()=>{try{return JSON.stringify({value:('+code+')})}catch(e){return JSON.stringify({error:e.message,stack:e.stack})}})()').js;
    if("'!result) throw Error('"'Script failed: '+code);
    const out = JSON.parse(result);
    if(out.error) throw Error(out.error+' in '+code);
    return out.value;
  }
  function act(code) {return js('(()=>{'+code+'})()');}
  function eq(actual,expected,label) {if(JSON.stringify(actual)"'!==JSON.stringify(expected))throw Error(label+'"': '+JSON.stringify(actual)+' "'!= '"'+JSON.stringify(expected));}
  function pause(ms) {"'$.NSRunLoop.currentRunLoop.runUntilDate($.NSDate.dateWithTimeIntervalSinceNow(ms/1000));}
  function ready() {
    for(let i=0;i<50;i++) {
      pause(65);
      if(js('"'document.readyState')==='complete' && js('document.querySelectorAll(\".row-select\").length')===4) return;
    }
    throw Error('Page did not load');
  }
  function resize(w,h) {web.setFrameSize("'$.NSMakeSize(w,h)); pause(65); eq(js('"'innerWidth'),w,'Viewport resized');}
  function shot(name) {
    web.displayIfNeeded;
    const bitmap = web.bitmapImageRepForCachingDisplayInRect(web.bounds);
    web.cacheDisplayInRectToBitmapImageRep(web.bounds,bitmap);
    bitmap.representationUsingTypeProperties(4,"'$.NSDictionary.dictionary).writeToFileAtomically(root+'"'/.relay-check/'+name+'.png',true);
  }
  const req="'$.NSURLRequest.requestWithURL($.NSURL.fileURLWithPath(root+'"'/index.html'));
  web.mainFrame.loadRequest(req); ready();
  act('window.testErrors=[]; addEventListener(\"error\",e=>testErrors.push(e.message));');
  const fileData = "'$.NSData.dataWithContentsOfFile(root+'"'/DATA.json');
  eq(js('snapshot'), JSON.parse("'$.NSString.alloc.initWithDataEncoding(fileData,4).js),'"'Snapshot content');
  eq(js('document.querySelectorAll(\".metric\").length'),4,'Metric count');
  shot('desktop');
  for(const w of [1920,1440,1280,1150,1081,1024,800,701,700,390,375,320]) {
    resize(w,844);
    eq(js('document.documentElement.scrollWidth'),w,'Horizontal page overflow at '+w);
    eq(js('Array.from(document.querySelectorAll(\".queue, .metric, .panel-head, .plot, .topbar, .filters, .chart-stats\")).filter(e=>e.scrollWidth>e.clientWidth+1).map(e=>[e.className,e.scrollWidth,e.clientWidth])'),[],'Clipped contents at '+w);
  }
  resize(390,844);
  shot('mobile');
  act('document.querySelector(\\'[data-id=\"INC-2839\"] .row-select\\').click();');
  eq(js('document.activeElement.id'),'incident-detail','Compact selection focus');
  eq(js('document.querySelector(\".detail-meta .incident-id\").textContent'),'INC-2839','Selected details');
  pause(70);
  shot('mobile-detail');
  act('document.getElementById(\"back-link\").click()');
  eq(js('document.activeElement.closest(\"tr\").dataset.id'),'INC-2839','Return focus');
  act('document.getElementById(\"critical-shortcut\").click()');
  eq(js('document.querySelectorAll(\".row-select\").length'),1,'Critical filter');
  act('document.getElementById(\"acknowledge\").click()');
  eq(js('document.querySelector(\".selected .status\").textContent'),'Acknowledged','Acknowledged in table');
  eq(js('document.getElementById(\"acknowledge\").disabled'),true,'Acknowledgement button');
  eq(js('testErrors'),[],'WebKit errors');
  web.mainFrame.reload; ready();
  eq(js('document.getElementById(\"acknowledge\").disabled'),true,'Persisted acknowledgement');
  act('window.testErrors=[]; addEventListener(\"error\",e=>testErrors.push(e.message));');
  act('const q=document.getElementById(\"search-input\"); q.value=\"unknown service\"; q.dispatchEvent(new Event(\"input\"));');
  eq(js('document.getElementById(\"queue-empty\").hidden'),false,'Empty state');
  eq(js('document.querySelector(\"#detail-body\").innerText.includes(\"No incident selected\")'),true,'Empty detail');
  act('document.getElementById(\"reset-filters\").click()');
  eq(js('document.querySelectorAll(\".row-select\").length'),4,'Reset filters');
  act('const q=document.getElementById(\"search-input\"); q.value=\"SILVA index\"; q.dispatchEvent(new Event(\"input\"));');
  eq(js('document.querySelector(\"tr.selected\").dataset.id'),'INC-2837','Multi-term search');
  act('const q=document.getElementById(\"search-input\"); q.value=\"\"; q.dispatchEvent(new Event(\"input\"));');
  for(const hours of [6,12,24]) {
    act('document.querySelector(\\'[data-hours=\"'+hours+'\"]\\').click();');
    eq(js('document.getElementById(\"plot\").getAttribute(\"aria-valuemin\")'),String(24-hours),'Chart range');
    act('const p=document.getElementById(\"plot\"); p.focus(); p.dispatchEvent(new KeyboardEvent(\"keydown\",{key:\"Home\",bubbles:true}));');
    eq(js('document.getElementById(\"plot\").getAttribute(\"aria-valuenow\")'),String(24-hours),'Keyboard sample inspection');
    act('document.getElementById(\"plot\").dispatchEvent(new KeyboardEvent(\"keydown\",{key:\"ArrowRight\",bubbles:true}));');
    eq(js('document.getElementById(\"plot\").getAttribute(\"aria-valuenow\")'),String(25-hours),'Keyboard next sample');
  }
  act('document.body.dispatchEvent(new KeyboardEvent(\"keydown\",{key:\"?\",bubbles:true}));');
  eq(js('document.getElementById(\"shortcuts\").open'),true,'Show keyboard help');
  act('document.getElementById(\"close-shortcuts\").click(); document.body.dispatchEvent(new KeyboardEvent(\"keydown\",{key:\"/\",bubbles:true}));');
  eq(js('document.activeElement.id'),'search-input','Focus search');
  resize(1280,800);
  act('document.querySelector(\\'[data-id=\"INC-2832\"] .row-select\\').click();');
  eq(js('document.activeElement.closest(\"tr\").dataset.id'),'INC-2832','Desktop selection focus');
  eq(js('getComputedStyle(document.querySelector(\"#incidents\")).display'),'block','Queue rendered');
  eq(js('testErrors'),[],'WebKit errors');
  eq(js('performance.getEntriesByType(\"resource\").filter(e=>/"'^https?:/.test(e.name)).length'"'),0,'No web resources');
  return 'WebKit verified all seed data, four metrics, responsive fit at 12 sizes, selection/focus, acknowledgement persistence, search, severity filter, empty/reset, chart controls, shortcuts and zero web resources.';
}
EOF
